#!/usr/bin/env bash
# scripts/gate_cross_consumer_parity.sh — CM-CROSS-CONSUMER-PARITY gate
# (T-P7.02, HXC-159 Phase P7).
#
# Purpose: proves HelixCode's and HelixAgent's own capability-manifest
# reports (T-P7.01, generated by cmd/skillconformance in each module) carry
# no UNEXPLAINED asymmetry — every loader_api_surface flag and every
# registered skill either agrees between the two consumers, or is
# explicitly, mutually marked optional (OptionalCapabilities on BOTH
# reports) with a real reason. Exits 0 (PASS) iff the diff is empty modulo
# marked-optional entries; exits non-zero (FAIL) and names every unexplained
# asymmetry otherwise.
#
# Usage:
#   scripts/gate_cross_consumer_parity.sh HELIX_CODE_REPORT.json HELIX_AGENT_REPORT.json
#
# The two report arguments are REQUIRED — this gate does not itself invoke
# either consumer's skillconformance CLI (report generation depends on
# per-environment skill-directory configuration this gate does not own).
#
# Paired mutation (§1.1): internal/skillparity/parity_test.go's
# TestDiff_SkillRegisteredInOnlyOneConsumerFails exercises this exact gate
# logic (register a fixture skill in one report only, no optional-capability
# mark) and proves Diff().OK() is false; this script is the shell-invocable
# entry point to that same internal/skillparity.Diff function via
# cmd/skillparity.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
MODULE_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"

if [ "$#" -ne 2 ]; then
	echo "usage: $0 HELIX_CODE_REPORT.json HELIX_AGENT_REPORT.json" >&2
	exit 2
fi

A_REPORT="$1"
B_REPORT="$2"

if [ ! -f "$A_REPORT" ]; then
	echo "CM-CROSS-CONSUMER-PARITY: FAIL — report not found: $A_REPORT" >&2
	exit 1
fi
if [ ! -f "$B_REPORT" ]; then
	echo "CM-CROSS-CONSUMER-PARITY: FAIL — report not found: $B_REPORT" >&2
	exit 1
fi

cd "$MODULE_ROOT"
if go run ./cmd/skillparity -a "$A_REPORT" -b "$B_REPORT"; then
	echo "CM-CROSS-CONSUMER-PARITY: PASS" >&2
	exit 0
fi
echo "CM-CROSS-CONSUMER-PARITY: FAIL — see the printed diff above for unexplained asymmetries" >&2
exit 1
